(40583,135861,0,0,'What about the Al\'Aketh? Can they help?',0,0,0,40582,0,NULL,0,0,NULL,0,NULL,NULL,70124),
(40584,135862,0,0,'How do we solve this?',0,0,0,40583,0,NULL,0,0,NULL,0,NULL,NULL,70124),
(40585,135863,0,0,'Do we know why..?',0,0,0,40584,0,NULL,0,0,NULL,0,NULL,NULL,70124),
